import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
table = [r for r in records if r['source'] == '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture7/15.csv' and r['values'].get('Task Time Required', '') != 'Worker']
worker_ids = [str(i) for i in range(1, 13)]
task_ids = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J']
c = {}
for row in table:
    worker = row['values']['Task Time Required']
    for t in task_ids:
        val = row['values'][t]
        if val == '':
            raise ValueError(f'Missing time for worker {worker}, task {t}')
        c[worker, t] = int(val)
for i in worker_ids:
    for t in task_ids:
        if (i, t) not in c:
            raise ValueError(f'Missing c coefficient for worker {i}, task {t}')
m = gp.Model('worker_task_assignment')
x_vars = m.addVars(worker_ids, task_ids, vtype=GRB.BINARY, name='')
y_vars = m.addVars(worker_ids, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((c[i, t] * x_vars[i, t] for i in worker_ids for t in task_ids)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, t] for i in worker_ids)) == 1 for t in task_ids), name='')
m.addConstrs((gp.quicksum((x_vars[i, t] for t in task_ids)) == y_vars[i] for i in worker_ids), name='')
m.addConstr(gp.quicksum((y_vars[i] for i in worker_ids)) == 10, name='select_10')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')